from fractions import Fraction
def mine(z, s):
    d = 1 << s
    if d == 1:
        return z
    h = d >> 1
    if z >= 0:
        return (z + h) // d
    return -((h - z) // d)
def ref(z, s):
    # round half away from zero using Fraction
    q = Fraction(z, 1 << s)
    if q >= 0:
        # floor(q + 1/2)
        return int((q + Fraction(1,2)).__floor__())
    else:
        return -int(((-q) + Fraction(1,2)).__floor__())
bad=0
for s in range(0,17):
    for z in range(-5000, 5001):
        a=mine(z,s); b=ref(z,s)
        if a!=b:
            bad+=1
            if bad<10: print("diff", z, s, a, b)
print("rounding check done, mismatches:", bad)
# also verify ties explicitly
print(mine(-3,1), mine(3,1), mine(-1,1), mine(1,1), mine(-5,2), mine(5,2), mine(2,2), mine(-2,2), mine(6,2), mine(-6,2))
